using TownOfHost;using TownOfHost.Roles.Core;using TownOfHost.Roles.Impostor;using UnityEngine;
class Program{
static int passed; static void Check(bool b,string m){if(!b)throw new Exception(m);}static void Test(string n,Action a){AmongUsClient.Instance=new();GameStates.IsMeeting=true;GameStates.IsInTask=true;Utils.Messages.Clear();CustomRoleManager.Resolved=CustomRoleManager.Deaths=0;Screen.fullScreen=false;Time.fixedDeltaTime=.02f;a();passed++;Console.WriteLine("PASS "+n);}
static (Experiencer e,PlayerControl me,PlayerControl target) Setup(){OptionItem.Items.Clear();Experiencer.RoleInfo.Setup();var me=new PlayerControl{PlayerId=1};var e=new Experiencer(me);me.Active=e;e.Add();return(e,me,new PlayerControl{PlayerId=2});}
static void Points(Experiencer e,PlayerControl me,PlayerControl t,int kills){for(int i=0;i<kills;i++)e.OnMurderPlayerAsKiller(new(me,t));}
static int Point(Experiencer e)=>int.Parse(e.GetProgressText().Split('(')[1].Split(')')[0]);
static void Main(){
Test("role registration and option defaults with unique offsets",()=>{var(e,me,t)=Setup();Check((int)Experiencer.RoleInfo.RoleName==369&&Experiencer.RoleInfo.ConfigId==95600&&Experiencer.RoleInfo.New,"registration");Check(OptionItem.Items.Count==11&&e.CalculateKillCooldown()==30&&OptionItem.Items[95604].Value==10&&OptionItem.Items[95605].Value==5,"defaults");Check(OptionItem.Items[95613].Parent==OptionItem.Items[95606]&&OptionItem.Items[95610].Parent==OptionItem.Items[95609],"option parents");});
Test("normal kills award points once per completed kill event",()=>{var(e,me,t)=Setup();e.OnMurderPlayerAsKiller(new(me,t));Check(Point(e)==10,"points");});
Test("self kill does not award points",()=>{var(e,me,t)=Setup();e.OnMurderPlayerAsKiller(new(me,me));Check(Point(e)==0,"suicide points");});
Test("task completion is validated and cannot be repeated",()=>{var(e,me,t)=Setup();me.Data.Tasks.Add(new(){Id=7});e.OnCompleteTask(8);e.OnCompleteTask(7);e.OnCompleteTask(7);Check(Point(e)==5,"invalid or repeated task points");});
Test("nonhost task completion cannot mutate point state",()=>{var(e,me,t)=Setup();me.Data.Tasks.Add(new(){Id=7});AmongUsClient.Instance.AmHost=false;e.OnCompleteTask(7);Check(Point(e)==0,"nonhost task");});
Test("meeting-only enchants reject task phase",()=>{var(e,me,t)=Setup();Points(e,me,t,10);GameStates.IsMeeting=false;Experiencer.Tryentrant(2,me);Check(me.Addons.Count==0&&Point(e)==100,"outside meeting");});
Test("dead players cannot buy enchants",()=>{var(e,me,t)=Setup();Points(e,me,t,10);me.Alive=false;Experiencer.Tryentrant(2,me);Check(me.Addons.Count==0,"dead enchant");});
Test("nonhosts cannot execute enchant mutation",()=>{var(e,me,t)=Setup();Points(e,me,t,10);AmongUsClient.Instance.AmHost=false;Experiencer.Tryentrant(2,me);Check(me.Addons.Count==0,"nonhost enchant");});
Test("insufficient points and invalid selection are rejected privately",()=>{var(e,me,t)=Setup();Experiencer.Tryentrant(2,me);Experiencer.Tryentrant(0,me);Experiencer.Tryentrant(7,me);Check(Point(e)==0&&me.Addons.Count==0&&Utils.Messages.All(x=>x.Target==1),"validation");});
Test("cooldown enchant clamps and survives cooldown calculation",()=>{var(e,me,t)=Setup();Points(e,me,t,3);OptionItem.Items[95613].Value=99;Experiencer.Tryentrant(1,me);Check(Point(e)==5&&e.CalculateKillCooldown()==0&&me.Syncs==1,"cooldown");Experiencer.Tryentrant(1,me);Check(Point(e)==5,"duplicate enchant");});
Test("Guesser and MagicHand granted once with configured cost",()=>{var(e,me,t)=Setup();Points(e,me,t,10);Experiencer.Tryentrant(2,me);Experiencer.Tryentrant(3,me);Experiencer.Tryentrant(3,me);Check(Point(e)==50&&me.Addons.SequenceEqual(new[]{CustomRoles.Guesser,CustomRoles.MagicHand}),"addons");});
Test("zero cost means disabled rather than free",()=>{var(e,me,t)=Setup();OptionItem.Items[95607].Value=0;Experiencer.Tryentrant(2,me);Check(me.Addons.Count==0,"disabled enchant");});
Test("delayed kill waits then resolves exactly once",()=>{var(e,me,t)=Setup();Points(e,me,t,4);Experiencer.Tryentrant(4,me);var info=new MurderInfo(me,t);e.OnCheckMurderAsKiller(info);Check(!info.DoKill,"instant kill");Time.fixedDeltaTime=5;e.OnFixedUpdate(me);Check(CustomRoleManager.Resolved==0,"early");e.OnFixedUpdate(me);e.OnFixedUpdate(me);Check(CustomRoleManager.Resolved==1&&Point(e)==10,"late or repeated");});
Test("guarded targets never enter the delayed queue",()=>{var(e,me,t)=Setup();Points(e,me,t,4);Experiencer.Tryentrant(4,me);e.OnCheckMurderAsKiller(new(me,t){Guard=true});Time.fixedDeltaTime=11;e.OnFixedUpdate(me);Check(CustomRoleManager.Resolved==0,"bypassed guard");});
Test("disconnected and recycled targets are discarded",()=>{var(e,me,t)=Setup();Points(e,me,t,4);Experiencer.Tryentrant(4,me);e.OnCheckMurderAsKiller(new(me,t));t.NetId++;Time.fixedDeltaTime=11;e.OnFixedUpdate(me);Check(CustomRoleManager.Resolved==0,"stale netId");});
Test("report resolves pending kill and cannot resolve twice",()=>{var(e,me,t)=Setup();Points(e,me,t,4);Experiencer.Tryentrant(4,me);e.OnCheckMurderAsKiller(new(me,t));e.OnReportDeadBody(t,null);e.OnReportDeadBody(t,null);Check(CustomRoleManager.Resolved==1,"report duplicate");});
Test("owner death cancels pending delayed kills",()=>{var(e,me,t)=Setup();Points(e,me,t,4);Experiencer.Tryentrant(4,me);e.OnCheckMurderAsKiller(new(me,t));e.OnDead(me);Time.fixedDeltaTime=11;e.OnFixedUpdate(me);Check(CustomRoleManager.Resolved==0,"owner death");});
Test("no-report enchant handles emergency buttons safely",()=>{var(e,me,t)=Setup();Points(e,me,t,6);Experiencer.Tryentrant(5,me);e.OnMurderPlayerAsKiller(new(me,t));var r=RoleBase.DontReportreson.None;Check(!e.CancelReportDeadBody(me,null,ref r),"emergency null");Check(e.CancelReportDeadBody(me,new(){PlayerId=2},ref r),"reportable");});
Test("bodyless kill uses common death callbacks and honors guard",()=>{var(e,me,t)=Setup();Points(e,me,t,7);Experiencer.Tryentrant(6,me);Check(!e.TryNoBodyKill(new(me,t){Guard=true}),"guard");Check(e.TryNoBodyKill(new(me,t))&&t.Exiles==1&&CustomRoleManager.Deaths==1&&Point(e)==10,"bodyless death hooks");});
Test("role RPC roundtrip keeps points flags and reduced cooldown",()=>{var(e,me,t)=Setup();Points(e,me,t,10);Experiencer.Tryentrant(1,me);var data=RoleBase.LastRpc.ToArray();var other=new PlayerControl{PlayerId=3};var copy=new Experiencer(other);other.Active=copy;copy.Add();copy.ReceiveRPC(new Hazel.MessageReader(data));Check(Point(copy)==75&&copy.CalculateKillCooldown()==0,"RPC state");});
Test("auto focus avoids null destroyed hidden disabled and fullscreen inputs",()=>{SafeFocus.Give(null);var box=new TextBoxTMP{gameObject=null};SafeFocus.Give(box);box.gameObject=new(){activeInHierarchy=false};SafeFocus.Give(box);box.gameObject.activeInHierarchy=true;box.isActiveAndEnabled=false;SafeFocus.Give(box);box.isActiveAndEnabled=true;Screen.fullScreen=true;SafeFocus.Give(box);Check(box.Calls==0,"unsafe focus");Screen.fullScreen=false;SafeFocus.Give(box);Check(box.Calls==1,"valid focus");});
Test("host local color never broadcasts",()=>{PlayerControl.LocalPlayer=new(){PlayerId=1};var t=new PlayerControl{PlayerId=2};CustomRpcSender.Destinations.Clear();t.RpcChColor(PlayerControl.LocalPlayer,6);Check(t.Color==6&&CustomRpcSender.Destinations.Count==0,"local color leaked");});
Test("unknown receiver cannot fall back to broadcast",()=>{PlayerControl.LocalPlayer=new(){PlayerId=1};var t=new PlayerControl{PlayerId=2};var viewer=new PlayerControl{PlayerId=3,ClientId=-1};CustomRpcSender.Destinations.Clear();t.RpcChColor(viewer,6);t.RpcHideSkinAndPet(viewer);Check(CustomRpcSender.Destinations.Count==0,"broadcast fallback");});
Test("remote color and cosmetics use exactly the selected client",()=>{PlayerControl.LocalPlayer=new(){PlayerId=1};var t=new PlayerControl{PlayerId=2};var viewer=new PlayerControl{PlayerId=3,ClientId=77};CustomRpcSender.Destinations.Clear();t.RpcChColor(viewer,6);t.RpcHideSkinAndPet(viewer);Check(CustomRpcSender.Destinations.SequenceEqual(new[]{77,77}),"wrong receiver");});
Test("lobby appearance is not changed by game color effects",()=>{PlayerControl.LocalPlayer=new(){PlayerId=1};var t=new PlayerControl{PlayerId=2};GameStates.IsLobby=true;CustomRpcSender.Destinations.Clear();t.RpcChColor(PlayerControl.LocalPlayer,6);t.RpcHideSkinAndPet(new(){PlayerId=3});Check(CustomRpcSender.Destinations.Count==0&&t.Color==0,"lobby effect");GameStates.IsLobby=false;});
Console.WriteLine($"RESULT {passed} passed, 0 failed");}}
